<!doctype html><html lang="es"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:11px;color:#222}header{border-bottom:2px solid #0d6efd;margin-bottom:16px;padding-bottom:8px}.muted{color:#666}table{width:100%;border-collapse:collapse}th{background:#e9f2ff;border:1px solid #ccd}td{border:1px solid #ddd;padding:6px}.right{text-align:right}.total{font-size:14px;font-weight:bold;text-align:right;margin-top:12px}footer{position:fixed;bottom:0;width:100%;text-align:center;color:#777;font-size:9px}</style></head><body><header><h2>Farmacia San Juan Bautista</h2><div>Reporte general de ventas</div><div class="muted">Generado: {{ now()->format('d/m/Y H:i') }} @if($from) · Desde {{ $from }} @endif @if($to) · Hasta {{ $to }} @endif</div></header><table><thead><tr><th>Fecha</th><th>Cliente</th><th>Vendedor</th><th class="right">Total</th></tr></thead><tbody>@foreach($sales as $sale)<tr><td>{{ $sale->date->format('d/m/Y H:i') }}</td><td>{{ $sale->customer?->name }}</td><td>{{ $sale->user?->name }}</td><td class="right">S/ {{ number_format($sale->total,2) }}</td></tr>@endforeach</tbody></table><div class="total">Total ventas: S/ {{ number_format($total,2) }}</div><footer>Página <span class="page"></span></footer></body></html>
